import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "Documents from another tenant are invisible",
    { tag: "@DOC-07" },
    async ({ apiAs }) => {
      // Background: signed in as member@northwind.test, with a vendor in status "draft"
      const northwindMember = await apiAs("member");
      const northwindVendorResponse = await northwindMember.post("/api/vendors", {
        data: {
          name: uniqueName("Northwind Doc Vendor"),
          category: "services",
          contact_email: "billing@northwind-vendor.test",
        },
      });
      expect(northwindVendorResponse.status()).toBe(201);
      const northwindVendor = await northwindVendorResponse.json();
      expect(northwindVendor.status).toBe("draft");

      // Given a document exists in tenant "Globex Procurement"
      const globexMember = await apiAs("otherTenant");
      const globexVendorResponse = await globexMember.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Doc Vendor"),
          category: "logistics",
          contact_email: "ap@globex-vendor.test",
        },
      });
      expect(globexVendorResponse.status()).toBe(201);
      const globexVendor = await globexVendorResponse.json();

      const uploadResponse = await globexMember.post(
        `/api/vendors/${globexVendor.id}/documents`,
        {
          multipart: {
            kind: "w9",
            file: {
              name: "w9.pdf",
              mimeType: "application/pdf",
              buffer: Buffer.from("%PDF-1.4 globex w9 fixture"),
            },
          },
        },
      );
      expect(uploadResponse.status()).toBe(201);
      const globexDocument = await uploadResponse.json();
      expect(globexDocument.id).toBeTruthy();

      // When I request that document by id (as the northwind member)
      const response = await northwindMember.get(`/api/documents/${globexDocument.id}`);

      // Then the response status is 404 and the error code is "document_not_found"
      expect(response.status()).toBe(404);
      const body = await response.json();
      expect(body.error.code).toBe("document_not_found");
    },
  );
});
